  1: [CmdletBinding()]
  2: param(
  3:   [Parameter(Mandatory)][string]$RunRoot
  4: )
  5: 
  6: Set-StrictMode -Version Latest
  7: $ErrorActionPreference = 'Stop'
  8: 
  9: $rootFull = [IO.Path]::GetFullPath($RunRoot)
 10: $runsRoot = [IO.Path]::GetFullPath('D:\Lawbeach\lawbench-B\docs\plan\evidence\T32\NativeDocumentCitationEntry-20261027-190830\runs')
 11: if ([IO.Path]::GetDirectoryName($rootFull).TrimEnd('\') -ine $runsRoot.TrimEnd('\') -or
 12:     $rootFull -notmatch '\\T32-citation-[0-9]{8}-[0-9]{6}$') {
 13:   throw "refusing non-T32-citation run root: $rootFull"
 14: }
 15: 
 16: $StateDir = Join-Path $rootFull 'gui\state'
 17: $StatePath = Join-Path $StateDir 'current.json'
 18: $StopRequestPath = Join-Path $StateDir 'stop-request.json'
 19: $StopReportPath = Join-Path $StateDir 'stop-report.json'
 20: $FallbackReportPath = Join-Path $StateDir 'stop-report-fallback.json'
 21: if (-not (Test-Path -LiteralPath $StatePath -PathType Leaf)) {
 22:   throw "no T33 GUI state: $StatePath"
 23: }
 24: 
 25: function Write-JsonNoBom([string]$Path, $Value) {
 26:   $temporary = "$Path.tmp-$PID"
 27:   $Value | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $temporary -Encoding utf8NoBom
 28:   Move-Item -Force -LiteralPath $temporary -Destination $Path
 29: }
 30: 
 31: function Get-ExactIdentity([int]$TargetPid) {
 32:   $process = Get-Process -Id $TargetPid -ErrorAction SilentlyContinue
 33:   if (-not $process) { return $null }
 34:   try {
 35:     $commandLine = ''
 36:     try {
 37:       $cim = Get-CimInstance Win32_Process -Filter "ProcessId = $TargetPid" -ErrorAction Stop
 38:       if ($cim) { $commandLine = [string]$cim.CommandLine }
 39:     } catch {}
 40:     return [pscustomobject]@{
 41:       pid = $process.Id
 42:       executablePath = [IO.Path]::GetFullPath($process.Path)
 43:       startTimeUtcTicks = [string]$process.StartTime.ToUniversalTime().Ticks
 44:       commandLine = $commandLine
 45:     }
 46:   } catch {
 47:     return $null
 48:   }
 49: }
 50: 
 51: function Test-ExactRecord($Record) {
 52:   $current = Get-ExactIdentity ([int]$Record.pid)
 53:   if (-not $current) { return $false }
