 51:     $item = Get-Item -LiteralPath $current -Force
 52:     if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {
 53:       throw "reparse point refused: $current"
 54:     }
 55:   }
 56: }
